export function mockApi(path: string) {
  if (path.includes("/api/admin/ai")) return { ok: true, json: { ok: true, text: "Köszönjük! 💛 Igen: töltsd fel a bőrödről egy fotót, és megmutatja a tetoválást ma, 10, 30 és 50 év múlva." } };
  if (path.includes("/api/admin/reply")) return { ok: true, json: { ok: true } };
  if (path.includes("/test/")) return { ok: true, json: { ok: true, msg: "A kulcsok jók. Most jöhet az Összekapcsolás." } };
  if (path.includes("email-status")) return { ok: true, json: { resend_key_works: true, sending_domain: { name: "inkage.app", status: "verified" }, emails: { signup_confirmation: true, password_reset: true, welcome: true, password_changed: true } } };
  if (path.includes("status")) return { ok: true, json: { service_role: true, cron: false, tiktok: true, instagram: true, gsc: false, email: true, telegram: false, apple: true, apple_sales: false, google_play: true, google_installs: false, ai: !new URLSearchParams(location.search).has("nokey"), gsc_site: "sc-domain:inkage.app", redirect_tiktok: "https://inkage.app/api/admin/callback/tiktok", redirect_instagram: "https://inkage.app/api/admin/callback/instagram" } };
  if (path.includes("email-status")) return { ok: true, json: { resend_key_works: true, sending_domain: { name: "inkage.app", status: "verified" }, emails: { signup_confirmation: true, password_reset: true, welcome: true, password_changed: true } } };
  if (path.includes("digest")) return { ok: true, json: { ok: true, email: "elküldve", plan: "elkészült" } };
  if (path.includes("/api/admin/push")) return { ok: true, json: { ok: true, sent: 1, key: "x", items: [] } };
  if (path.includes("/api/admin/inbox") || path.includes("/api/admin/lock") || path.includes("/api/admin/publish")) return { ok: true, json: { ok: true, results: {} } };
  return { ok: true, json: { ok: true, tiktok: "31 poszt", instagram: "58 poszt", gsc: "nincs beállítva" } };
}

